function XUiPunishaarFightMain:_OpenBasePanel()
    if self.CurPanel then
        self.CurPanel:Close()
    end
    self:_HideTalkTips()

    -- 顶部 HUD 按 Base 归属配置（无论 PanelBase 是否就位都先配，降级时也正确）
    self.PanelTop:SetShowOnBase()

    -- Base 无战斗上下文：释放商人/敌人模型（从 Shopping 切来时商人需释放）#商人接入
    if self.ModelShow then
        self.ModelShow:ReleaseEnemyModel()
    end
    -- 敌方副卡槽对称关闭（Base 无敌人模型）#副卡槽联动
    if self.PanelTop and self.PanelTop.RoleModelUiShow then
        self.PanelTop.RoleModelUiShow:HideEnemyDetail()
    end

    if not self.PanelBase then
        XLog.Error("[PunishaarFightMain] _OpenBasePanel: PanelBase 节点缺失，请检查 FightMain prefab 是否已加 PanelBase")
        return
    end

    if not self.BasePanel then
        ---@type XUiPunishaarFightMainPanelBase
        self.BasePanel = XUiPunishaarFightMainPanelBase.New(self.PanelBase, self)
    end

    self.BasePanel:Open()

    -- Base 态无战斗上下文：不预览敌人模型（与 PreFight/Fighting 的 RefreshEnemyModel 对称省略）#66
    self.CurPanel = self.BasePanel
end

function XUiPunishaarFightMain:_OpenPreFightPanel()
    if self.CurPanel then
        self.CurPanel:Close()
    end
    self:_HideTalkTips()

    if not self.PreFightPanel then
        ---@type XUiPunishaarFightMainPanelFightBefore
        self.PreFightPanel = XUiPunishaarFightMainPanelFightBefore.New(self.PanelFightBefore, self)
    end

    self.PreFightPanel:Open()
    self.PanelTop:SetShowOnPreFight()

    -- 战前预览敌人/Boss 模型（契约 fightId→Fight.EnemyId→Enemy.EnemyModel）#63
    if self.ModelShow then
        self.ModelShow:RefreshEnemyModel()
    end
    -- 敌方副卡槽对称显（PreFight 有敌人模型）#副卡槽联动
    if self.PanelTop and self.PanelTop.RoleModelUiShow then
        self.PanelTop.RoleModelUiShow:ShowEnemyDetail()
    end

    self.CurPanel = self.PreFightPanel
end

function XUiPunishaarFightMain:_OpenShopPanel()
    if self.CurPanel then
        self.CurPanel:Close()
    end
    self:_HideTalkTips()

    -- 补强商店显默认 group HUD（补强是战斗节点 Remedy 状态非独立节点，无法配 StageContent.HudGroupId，
    -- 共用 PunishaarConfig.RemedyShopHudGroupId；SelectHudByGroup 在切态末 _RefreshGuideTips 前调，确保读到新 _HudCfg）#补强HUD
    if self._Control:IsInRemedyShop() then
        local remedyShopHudGroupId = self._Control:GetRemedyShopHudGroupId()
        local gc = self._Control.GameControl
        if gc then
            gc:SelectHudByGroup(remedyShopHudGroupId)
        end
    end

    if not self.ShopPanel then
        ---@type XUiPunishaarFightMainPanelShop
        self.ShopPanel = XUiPunishaarFightMainPanelShop.New(self.PanelShop, self)
    end

    self.ShopPanel:Open()
    self.PanelTop:SetShowOnShop()

    -- Shop 无战斗上下文：释放敌人模型（主卡保留——战斗区卡在 Shop 仍显）+ 加载商人模型 #商人接入
    if self.ModelShow then
        self.ModelShow:ReleaseEnemyModel()
        local shopId = self._Control:GetCurrentShopId()
        if shopId and shopId > 0 then
            local shopCfg = self._Control.GameControl:GetTablePunishaarShop(shopId, true)
            if shopCfg then
                -- 商人模型+待机动画：TraderModelId 空则不加载（ShowShopNpcModel 内判空）；动画须模型加载完成后播（callback 内）
                self.ModelShow:ShowShopNpcModel(shopCfg.TraderModelId, shopCfg.NormalIdleAnima)
                -- 商人对话文本：ShopDialog 非空显 TalkTips 设 TxtTalk，空则隐（FightMain Shopping 态接入 #对话接入）
                if not string.IsNilOrEmpty(shopCfg.ShopDialog) then
                    self:_ShowTalkTips(shopCfg.ShopDialog)
                else
                    self:_HideTalkTips()
                end
            end
        end
    end
    -- 敌方副卡槽对称关闭（Shop 无敌人模型，替商人 NPC）#副卡槽联动
    if self.PanelTop and self.PanelTop.RoleModelUiShow then
        self.PanelTop.RoleModelUiShow:HideEnemyDetail()
    end

    self.CurPanel = self.ShopPanel
end

function XUiPunishaarFightMain:_OpenFightingPanel()
    if self.CurPanel then
        self.CurPanel:Close()
    end
    self:_HideTalkTips()

    if not self.FightingPanel then
        ---@type XUiPunishaarFightMainPanelFighting
        self.FightingPanel = XUiPunishaarFightMainPanelFighting.New(self.PanelFighting, self)
    end
    
    self.FightingPanel:Open()
    self.PanelTop:SetShowOnFighting()

    -- Fighting 态确保敌人模型加载（与 PreFight 对称；经 PreFight 进则 persist 无害，直接进则补加载）。#63
    if self.ModelShow then
        self.ModelShow:RefreshEnemyModel()
    end
    -- 敌方副卡槽对称显（Fighting 有敌人模型）#副卡槽联动
    if self.PanelTop and self.PanelTop.RoleModelUiShow then
        self.PanelTop.RoleModelUiShow:ShowEnemyDetail()
    end

    self.CurPanel = self.FightingPanel
end

