end

--- 拖拽开始：自动关 Tips 防视觉遮挡（订阅 EVENT_PUNISHAAR_DRAG_BEGIN；Hide 幂等，无 Tips 时无副作用）。§11
function XUiPunishaarFightMain:_OnDragBegin()
    self:HideTips()
end

--endregion

--region ------------------3D 模型转发（#63）-------------------

--- 展示主卡 3D 模型（slot 默认 1）。查 PunishaarCardModel 取 ModelId + NormalIdleAnima；无行→no-op（2D fallback）。
---@param cardId number 卡牌模板 Id
---@param slotIndex number|nil 卡牌挂点索引 1..N
function XUiPunishaarFightMain:ShowCardModel(cardId, slotIndex)
    if self.ModelShow then
        self.ModelShow:ShowCardModel(cardId, slotIndex)
    end
end

--- 展示敌人 3D 模型（直喂 modelName = enemyCfg.EnemyModel）。
---@param modelName string
---@param idleAnima string|nil
function XUiPunishaarFightMain:ShowEnemyModel(modelName, idleAnima)
    if self.ModelShow then
        self.ModelShow:ShowEnemyModel(modelName, idleAnima)
    end
end

--- 隐藏/释放当前模型（关 Tips/切对象时调，回缓存池）。
function XUiPunishaarFightMain:HideModel()
    if self.ModelShow then
        self.ModelShow:ReleaseModel()
    end
end

--endregion

return XUiPunishaarFightMain
